INSERT INTO anexos (entidade_tipo, entidade_id, categoria, storage_path, nome, mime, tamanho, owner_id, observacao)
SELECT 'comercial_comissoes', (SELECT id FROM comercial_comissoes WHERE codigo = v.ref), 'financeiro',
  'homologacao/'||v.code||'.pdf', 'Autorizacao comissao.pdf', 'application/pdf', 51200, '0dad00e4-ba12-4c54-bc4c-582c4bead2eb'::uuid,
  v.code||'|HOMOLOGACAO_FIXA_D18|documento_mock=true'
FROM (VALUES ('HOMO-D18-ANX-COM-001','HOMO-D18-COM-001'),('HOMO-D18-ANX-COM-002','HOMO-D18-COM-002'),('HOMO-D18-ANX-COM-003','HOMO-D18-COM-003'),('HOMO-D18-ANX-COM-004','HOMO-D18-COM-004'),('HOMO-D18-ANX-COM-005','HOMO-D18-COM-005')) v(code, ref)
WHERE (SELECT id FROM comercial_comissoes WHERE codigo = v.ref) IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM anexos a WHERE a.observacao LIKE v.code||'|%');